-- Synthetic fixtures only, one request, always rollback. No sends/provider calls.
begin;
do $$
declare c uuid:=gen_random_uuid(); c2 uuid:=gen_random_uuid(); s uuid:=gen_random_uuid(); s2 uuid:=gen_random_uuid(); r uuid:=gen_random_uuid(); f uuid:=gen_random_uuid(); f2 uuid:=gen_random_uuid();
 n int; p text:='klick-test-'||gen_random_uuid(); name1 text:='Klickfixture-'||s; req uuid:=gen_random_uuid(); x jsonb; y jsonb; bid uuid; jid uuid; typ text;
 cfg jsonb:='{"spielfortsetzung":"weiterspielen","fordert_fortsetzung":true,"fordert_fortsetzung_fuer":false,"fordert_fortsetzung_ort":false,"fordert_strafe":true,"strafen":[],"fordert_strafe_mannschaft":false,"fordert_strafe_rolle":false,"fordert_strafe_nummer":false,"fordert_begruendung":true,"begruendung_muster":"Der Ball bleibt im Spiel.","begruendung_gewicht":1}';
 a jsonb:='{"spielfortsetzung":"weiterspielen","persoenliche_strafe":"keine","strafen":[],"begruendung":"Ball bleibt spielbar.","_begruendung":{"richtig":false,"status":"nachbessern","nachfrage":"Was ist an der Aktion für deine Entscheidung wichtig?","feedback":""}}';
begin
 insert into public.vereine(id,name) values(c,'Klickfeedback-Rollback'),(c2,'Fremd-Klickfeedback-Rollback');
 select coalesce(min(id),0)-1 into n from public.obmann_zugang;
 insert into public.obmann_zugang(id,passwort,verein_id) values(n,p,c),(n-1,p||'-fremd',c2);
 insert into public.schiedsrichter(id,name,verein_id,pin,ist_test) values(s,name1,c,'942781',false),(s2,'Fremde-'||s2::text,c2,'942782',false);
 x:=public.obmann_belohnung_aendern(p,name1,req,'box_vergeben',null,2,'Isolierter Test',null);
 y:=public.obmann_belohnung_aendern(p,name1,req,'box_vergeben',null,2,'Isolierter Test',null);
 if jsonb_array_length(y->'boxen')<>2 or jsonb_array_length(y->'verlauf')<>1 then raise exception 'TEST duplicate grant'; end if;
 begin perform public.obmann_belohnung_aendern(p,name1,req,'box_vergeben',null,3,'Isolierter Test',null); raise exception 'TEST altered retry accepted'; exception when raise_exception then if sqlerrm like 'TEST%' then raise; end if; end;
 begin perform public.obmann_belohnungen(p||'-fremd',name1); raise exception 'TEST cross-club stock'; exception when raise_exception then if sqlerrm like 'TEST%' then raise; end if; end;
 begin perform public.obmann_belohnungen('wrong',name1); raise exception 'TEST no password'; exception when raise_exception then if sqlerrm like 'TEST%' then raise; end if; end;
 bid:=(x#>>'{boxen,0,id}')::uuid;
 perform public.obmann_belohnung_aendern(p,name1,gen_random_uuid(),'box_entziehen',null,1,'Test zurücknehmen',bid);
 begin perform public.jokerbox_oeffnen(s,'942781',bid); raise exception 'TEST revoked box opened'; exception when raise_exception then if sqlerrm like 'TEST%' then raise; end if; end;
 x:=public.mein_jokerbestand(s,'942781');
 if jsonb_array_length(x->'boxen')<>1 then raise exception 'TEST stock not revoked'; end if;
 bid:=(x#>>'{boxen,0,id}')::uuid; x:=public.jokerbox_oeffnen(s,'942781',bid); y:=public.jokerbox_oeffnen(s,'942781',bid);
 if x->>'typ' not in ('serienjoker','zweiter-versuch') or x->>'typ' is distinct from y->>'typ' then raise exception 'TEST draw changed'; end if;
 insert into public.runden(id,bezeichnung,startet_am,endet_am) values(r,'Klickfeedback-Fixture',now()-interval '1 day',now()+interval '1 day');
 insert into public.fragen(id,frage_text,medium,antworttyp,aktiv) values(f,'Isolierte Iconfrage','text','entscheidung',true),(f2,'Isolierte Folgefrage','text','entscheidung',true);
 insert into public.runden_fragen(verein_id,runde_id,frage_id,position) values(c,r,f,1),(c,r,f2,2);
 perform public.frage_entscheidungsloesung_setzen(f,cfg); perform public.frage_entscheidungsloesung_setzen(f2,cfg);
 if private.hinweis_strafentext(f)<>'Persönliche Strafe: Keine persönliche Strafe' then raise exception 'TEST empty no-card hint'; end if;
 perform public.obmann_frage_jokerhinweis(p,f,'Achte auf die Ballkontrolle.',true);
 if public.obmann_frage_jokerhinweis(p||'-fremd',f,null,false)<>'' then raise exception 'TEST cross-club hint'; end if;
 for typ in select unnest(array['denkanstoss','fehlerlupe','zufallsbaustein','schluesselbaustein']) loop
  perform public.obmann_belohnung_aendern(p,name1,gen_random_uuid(),'joker_vergeben',typ,1,'Hinweisjoker testen',null);
  x:=public.quiz_hinweisjoker(s,'942781',f,typ,a-'_begruendung');
  y:=public.quiz_hinweisjoker(s,'942781',f,typ,a-'_begruendung');
  if x<>y or nullif(x->>'hinweis','') is null then raise exception 'TEST hint retry'; end if;
 end loop;
 if (select count(*) from private.quiz_hinweis_einsaetze where person=s)<>4 then raise exception 'TEST hint count'; end if;
 x:=public.obmann_joker_verlauf(p,name1);
 if jsonb_array_length(x)<>1 or jsonb_array_length(x#>'{0,hinweise}')<>4 then raise exception 'TEST admin hint audit %',x; end if;
 select jb.id into jid from private.jokerbestand jb where jb.person=s and jb.typ='denkanstoss';
 begin perform public.obmann_belohnung_aendern(p,name1,gen_random_uuid(),'joker_entziehen',null,1,'Benutzt nicht löschen',jid); raise exception 'TEST consumed joker revoked'; exception when raise_exception then if sqlerrm like 'TEST%' then raise; end if; end;
 begin perform public.quiz_hinweisjoker(s2,'942782',f,'denkanstoss','{}'); raise exception 'TEST cross-club question'; exception when raise_exception then if sqlerrm like 'TEST%' then raise; end if; end;
 if has_function_privilege('anon','public.entscheidung_nachfrage_kontext(uuid,uuid,text,jsonb)','execute') then raise exception 'TEST leaked context'; end if;
 x:=public.entscheidung_mit_nachfrage_speichern(s,f2,'942781',a,true,null);
 if x ? 'loesung' or x ? 'ergebnis' or x#>'{antwort,_begruendung}' is not null or not (x->>'nachbesserung_offen')::boolean then raise exception 'TEST premature solution %',x; end if;
 select to_jsonb(q) into y from public.meine_antworten_v2(s,'942781') q where frage_id=f2;
 if not (y#>>'{entscheidung,nachbesserung_offen}')::boolean or y#>'{entscheidung,loesung}' is not null then raise exception 'TEST reload leaks %',y; end if;
 begin perform public.entscheidung_mit_nachfrage_speichern(s,f2,'942781',a||'{"spielfortsetzung":"einwurf"}',true,null); raise exception 'TEST changed core'; exception when raise_exception then if sqlerrm like 'TEST%' then raise; end if; end;
 x:=public.entscheidung_mit_nachfrage_speichern(s,f2,'942781',a||'{"begruendung":"Der Ball bleibt unter Kontrolle.","_begruendung":{"richtig":true,"status":"richtig","feedback":"Passend."}}',true,null);
 if not (x->>'korrekt')::boolean then raise exception 'TEST clarification not correct'; end if;
 if not exists(select 1 from public.antworten where schiedsrichter_id=s and frage_id=f2 and korrekt and versuch_anzahl=2 and zweiter_freitext='Der Ball bleibt unter Kontrolle.') then raise exception 'TEST audit answer missing'; end if;
 y:=public.entscheidung_mit_nachfrage_speichern(s,f2,'942781',a,true,null);
 if y<>x then raise exception 'TEST final retry changed result'; end if;
 if (select count(*) from private.quiz_hinweis_einsaetze where person=s)<>4 then raise exception 'TEST regular clarification consumed joker'; end if;
 raise notice 'PASS: grants, retries, roles, revoke, hint effects, orange persistence and final audit';
end $$;
rollback;
